using System;using System.IO;using System.IO.Ports;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Threading;using Microsoft.Win32;using System.Runtime.InteropServices;
namespace KlipperWinForms {using Obj=Dictionary<string,object>;
 interface IFlashLink:IDisposable {void Write(byte[] bytes);byte[] ReadFrame();void Discard();}
 sealed class KatapultCommandException:Exception {
  internal readonly bool OnlyTimeouts;
  internal KatapultCommandException(byte command,bool onlyTimeouts,Exception cause):base("Katapult "+(command==0x11?"CONNECT":"명령")+"(0x"+command.ToString("X2")+") 처리 실패: "+cause.Message,cause){OnlyTimeouts=onlyTimeouts;}
 }
 sealed class ComLink:IFlashLink {
  SerialPort port;public ComLink(SerialPort p){port=p;}
  public void Write(byte[] b)=>port.Write(b,0,b.Length);
  int Byte(DateTime until){while(DateTime.UtcNow<until){try{return port.ReadByte();}catch(TimeoutException){}}throw new TimeoutException("보드 응답 시간 초과");}
  public byte[] ReadFrame(){DateTime until=DateTime.UtcNow.AddSeconds(3);while(true){if(Byte(until)!=1)continue;if(Byte(until)!=0x88)continue;byte ack=(byte)Byte(until),words=(byte)Byte(until);var data=new byte[words*4+8];data[0]=1;data[1]=0x88;data[2]=ack;data[3]=words;for(int i=4;i<data.Length;i++)data[i]=(byte)Byte(until);return data;}}
  public void Discard(){port.DiscardInBuffer();}public void Dispose(){port.Dispose();}
 }
 static class SerialFlash {
  internal static byte[] ConnectUart(IFlashLink link,Action verifyIdentity,Action<string> log,Action<int> sleep=null){
   sleep=sleep??Thread.Sleep;
   log("CH340/CH341: 열린 UART 연결에서 Katapult 응답을 확인합니다.");
   try{var reply=Command(link,0x11,null,2);log("Katapult 응답 확인 · UART 진입 요청을 생략합니다.");return reply;}
   catch(KatapultCommandException ex){if(!ex.OnlyTimeouts)throw;}
   verifyIdentity();log("Katapult 응답 없음 · 같은 UART 연결로 부트로더 진입을 한 번 요청합니다.");
   link.Discard();link.Write(Encoding.ASCII.GetBytes("~ \x1c Request Serial Bootloader!! ~"));sleep(1000);verifyIdentity();link.Discard();
   try{return Command(link,0x11);}
   catch(KatapultCommandException ex){throw new Exception("UART 진입 요청 후에도 Katapult CONNECT(0x11)를 확인하지 못했습니다. Klipper/Katapult의 UART 핀·속도·설치 상태를 확인하세요. 펌웨어는 기록하지 않았습니다. "+ex.Message,ex);}
  }
  internal static readonly object Gate=new object();
  [StructLayout(LayoutKind.Sequential)] struct DeviceInfo {public int Size;public Guid ClassGuid;public uint DevInst;public IntPtr Reserved;}
  [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern IntPtr SetupDiCreateDeviceInfoList(IntPtr guid,IntPtr parent);
  [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool SetupDiOpenDeviceInfo(IntPtr set,string id,IntPtr parent,uint flags,ref DeviceInfo info);
  [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool SetupDiGetDeviceRegistryProperty(IntPtr set,ref DeviceInfo info,uint property,out uint type,byte[] buffer,uint size,out uint required);
  [DllImport("setupapi.dll")] static extern bool SetupDiDestroyDeviceInfoList(IntPtr set);
  internal static string Location(string id){IntPtr set=SetupDiCreateDeviceInfoList(IntPtr.Zero,IntPtr.Zero);if(set==new IntPtr(-1))return "";try{var info=new DeviceInfo{Size=Marshal.SizeOf(typeof(DeviceInfo))};if(!SetupDiOpenDeviceInfo(set,id,IntPtr.Zero,0,ref info))return "";byte[] b=new byte[8192];if(SetupDiGetDeviceRegistryProperty(set,ref info,0x23,out uint type,b,(uint)b.Length,out uint size)){string path=Encoding.Unicode.GetString(b,0,(int)size).Split('\0')[0];return Regex.Replace(path,@"#USBMI\(.*$","");}return "";}finally{SetupDiDestroyDeviceInfoList(set);}}
  public static List<Obj> Ports(){var result=new List<Obj>();var ports=new HashSet<string>(SerialPort.GetPortNames(),StringComparer.OrdinalIgnoreCase);foreach(string bus in new[]{"USB","FTDIBUS"})using(var usb=Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Enum\"+bus)){if(usb==null)continue;foreach(string type in usb.GetSubKeyNames()){var m=Regex.Match(type,@"VID_([0-9A-F]{4})[&+]PID_([0-9A-F]{4})",RegexOptions.IgnoreCase);if(!m.Success)continue;using(var group=usb.OpenSubKey(type)){foreach(string instance in group.GetSubKeyNames())using(var key=group.OpenSubKey(instance))using(var parameters=key.OpenSubKey("Device Parameters")){string name=Convert.ToString(parameters?.GetValue("PortName"));if(!ports.Contains(name))continue;string desc=Convert.ToString(key.GetValue("FriendlyName")??key.GetValue("DeviceDesc")),manufacturer=Convert.ToString(key.GetValue("Mfg")),id=bus+"\\"+type+"\\"+instance,location=Location(id),serial=instance.Contains("&")?"":instance;int vid=Convert.ToInt32(m.Groups[1].Value,16),pid=Convert.ToInt32(m.Groups[2].Value,16);result.Add(new Obj{{"device",name},{"description",desc},{"vid",vid},{"pid",pid},{"serial_number",serial},{"location",location},{"manufacturer",manufacturer},{"product",desc},{"label",name+" | "+desc},{"details",desc+" | USB "+vid.ToString("X4")+":"+pid.ToString("X4")+" | S/N "+serial+" | "+location}});}}}}return result.OrderBy(p=>int.Parse(Json.S(p,"device").Substring(3))).ToList();}
  static bool Kind(Obj p,int pid)=>p.ContainsKey("vid")&&Convert.ToInt32(p["vid"])==0x1d50&&Convert.ToInt32(p["pid"])==pid;
  public static bool IsCh34x(Obj port) {
   if(port==null||!port.TryGetValue("vid",out var vendor)||!port.TryGetValue("pid",out var product)||vendor==null||product==null)return false;
   if(!int.TryParse(Convert.ToString(vendor),out int vid)||!int.TryParse(Convert.ToString(product),out int pid))return false;
   // Standard WCH asynchronous-serial IDs from the upstream ch341 driver.
   return vid==0x1a86 && new[]{0x7522,0x7523,0x5523}.Contains(pid);
  }
  public static string ResolveMode(Obj port,string requested,Action<string> log=null) {
   if(requested=="auto"&&IsCh34x(port)) {
    log?.Invoke("CH340/CH341 감지: 수동 모드로 전환합니다. USB 자동 진입 요청 없이 Katapult에 직접 연결합니다. 보드가 부트로더 상태여야 하며 UART 핀과 통신 속도가 일치해야 합니다.");
    return "manual";
   }
   return requested;
  }
  static Obj Checked(Obj expected){var actual=Ports().SingleOrDefault(p=>Json.S(p,"device").Equals(Json.S(expected,"device"),StringComparison.OrdinalIgnoreCase));if(actual==null)throw new Exception("선택한 COM 보드가 없습니다.");foreach(var field in new[]{"vid","pid","serial_number","location"})if(Json.S(expected,field)!=""&&Json.S(actual,field)!=Json.S(expected,field))throw new Exception("선택한 COM 보드가 변경되었습니다.");return actual;}
  static SerialPort Open(Obj p,int baud){var port=new SerialPort(Json.S(p,"device"),baud){ReadTimeout=250,WriteTimeout=3000,DtrEnable=true};try{port.Open();return port;}catch{port.Dispose();throw;}}
  static Obj Bootloader(Obj selected,string mode,int baud,Action<string> log){selected=Checked(selected);mode=ResolveMode(selected,mode,log);if(mode=="manual"||mode=="auto"&&Kind(selected,0x6177))return selected;if(mode=="auto"&&!Kind(selected,0x614e))throw new Exception("자동 진입은 Klipper USB 장치만 지원합니다. 수동 또는 UART를 선택하세요.");if(mode=="auto"&&Json.S(selected,"location")==""&&Json.S(selected,"serial_number")=="")throw new Exception("재연결 보드 식별 정보가 없습니다.");using(var port=Open(selected,mode=="auto"?1200:baud)){if(mode=="auto"){Thread.Sleep(100);try{port.DtrEnable=false;}catch(IOException ex){log(ex.Message);}}else{byte[] b=Encoding.ASCII.GetBytes("~ \x1c Request Serial Bootloader!! ~");port.Write(b,0,b.Length);Thread.Sleep(100);}}
   if(mode=="uart"){Thread.Sleep(1000);return Checked(selected);}DateTime end=DateTime.UtcNow.AddSeconds(25);while(DateTime.UtcNow<end){var candidates=Ports().Where(p=>Kind(p,0x6177)&&(Json.S(selected,"location")!=""?Json.S(selected,"location")==Json.S(p,"location"):Json.S(selected,"serial_number").Equals(Json.S(p,"serial_number"),StringComparison.OrdinalIgnoreCase))).ToList();if(candidates.Count>1)throw new Exception("여러 보드가 일치합니다.");if(candidates.Count==1){Thread.Sleep(3000);return Checked(candidates[0]);}Thread.Sleep(250);}throw new Exception("Katapult USB 재연결 시간 초과");
  }
  public static ushort Crc(IEnumerable<byte> b){uint crc=0xffff;foreach(uint v in b){uint data=v^(crc&255);data^=(data&15)<<4;crc=(((data<<8)|(crc>>8))^(data>>4)^(data<<3))&65535;}return (ushort)crc;}
  public static byte[] Frame(byte command,byte[] payload){if(payload.Length%4!=0)throw new Exception("Invalid protocol payload");byte[] b=new byte[payload.Length+8];b[0]=1;b[1]=0x88;b[2]=command;b[3]=(byte)(payload.Length/4);Array.Copy(payload,0,b,4,payload.Length);ushort crc=Crc(b.Skip(2).Take(payload.Length+2));b[b.Length-4]=(byte)crc;b[b.Length-3]=(byte)(crc>>8);b[b.Length-2]=0x99;b[b.Length-1]=3;return b;}
  public static byte[] Command(IFlashLink link,byte command,byte[] payload=null,int attempts=5){Exception error=null;bool onlyTimeouts=true;for(int attempt=0;attempt<attempts;attempt++){bool sent=false;try{link.Write(Frame(command,payload??new byte[0]));sent=true;for(int stale=0;stale<5;stale++){var r=link.ReadFrame();if(r.Length<12||r[0]!=1||r[1]!=0x88||r[r.Length-2]!=0x99||r[r.Length-1]!=3||r.Length!=r[3]*4+8||Crc(r.Skip(2).Take(r.Length-6))!=BitConverter.ToUInt16(r,r.Length-4))throw new Exception("Katapult 응답 CRC/길이 오류");if(r[2]!=0xa0||U.V32(r,4)!=command)continue;return r.Skip(8).Take(r.Length-12).ToArray();}throw new Exception("Unexpected protocol acknowledgement");}catch(Exception ex){error=ex;if(!sent||!(ex is TimeoutException))onlyTimeouts=false;link.Discard();Thread.Sleep(100);}}throw new KatapultCommandException(command,onlyTimeouts,error);}
  public static Obj Transfer(IFlashLink link,byte[] data,Obj info,bool check,Action<string> log,byte[] connectReply=null){byte[] reply=connectReply??Command(link,0x11);if(reply.Length<13)throw new Exception("Invalid CONNECT reply");uint block=U.V32(reply,8);if(!new uint[]{64,128,256,512}.Contains(block))throw new Exception("Invalid block size");string[] text=Encoding.UTF8.GetString(reply,12,reply.Length-12).TrimEnd('\0').Split('\0');var board=new Obj{{"mcu",text[0]},{"application_start",U.V32(reply,4)},{"block_size",block},{"protocol_version",reply[2]+"."+reply[1]+"."+reply[0]},{"software_version",text.Length>1?text[1]:"?"}};Safety.Compatible(info,board);log("Safety Check Passed: "+Json.S(board,"mcu")+" / 0x"+Convert.ToUInt32(board["application_start"]).ToString("X"));if(check)return new Obj{{"board",board},{"firmware",info}};if(U.Hash(data)!=Json.S(info,"sha256"))throw new Exception("BIN snapshot hash changed");uint address=Convert.ToUInt32(board["application_start"]);int count=(data.Length+(int)block-1)/(int)block;var padded=data.Concat(Enumerable.Repeat((byte)255,count*(int)block-data.Length)).ToArray();for(int i=0;i<count;i++){uint current=address+(uint)i*block;var payload=BitConverter.GetBytes(current).Concat(padded.Skip(i*(int)block).Take((int)block)).ToArray();if(U.V32(Command(link,0x12,payload),0)!=current)throw new Exception("Write address mismatch");if(i%32==0)log("Writing "+(i+1)+"/"+count);}Command(link,0x13);for(int i=0;i<count;i++){uint current=address+(uint)i*block;var read=Command(link,0x14,BitConverter.GetBytes(current));if(read.Length!=block+4||U.V32(read,0)!=current||!read.Skip(4).SequenceEqual(padded.Skip(i*(int)block).Take((int)block)))throw new Exception("펌웨어 읽기 검증 불일치");if(i%32==0)log("Verifying "+(i+1)+"/"+count);}Command(link,0x15);log("Programming Complete");return new Obj{{"board",board},{"firmware",info},{"verified",true}};}
  public static Obj Run(Obj req,Action<string> log){if(!Monitor.TryEnter(Gate))throw new Exception("다른 업로드가 진행 중입니다.");try{string file=Json.S(req,"firmware");var info=Safety.Inspect(file);byte[] data=File.ReadAllBytes(file);if(U.Hash(data)!=Json.S(info,"sha256")||Json.S(req,"sha256")!=Json.S(info,"sha256"))throw new Exception("선택 후 BIN 파일이 변경되었습니다.");int baud=req.ContainsKey("baud")?Convert.ToInt32(req["baud"]):250000;string mode=Json.S(req,"mode");if(!new[]{"auto","manual","uart"}.Contains(mode)||baud<1||baud>4000000)throw new Exception("잘못된 시리얼 설정입니다.");var requested=Json.D(req,"port");bool uartAuto=mode=="auto"&&IsCh34x(requested);var selected=uartAuto?Checked(requested):Bootloader(requested,mode,baud,log);SerialPort port=null;for(int i=0;i<5;i++){Checked(selected);try{port=Open(selected,baud);break;}catch(UnauthorizedAccessException){if(i==4)throw;Thread.Sleep(2000);}catch(IOException){if(i==4)throw;Thread.Sleep(2000);}}using(var link=new ComLink(port)){if(uartAuto){log("UART 연결: "+Json.S(selected,"device")+" · "+baud+" baud");link.Discard();var reply=ConnectUart(link,()=>{Checked(selected);},log);return Transfer(link,data,info,Json.S(req,"action")=="check",log,reply);}link.Write(Frame(0x90,new byte[0]));return Transfer(link,data,info,Json.S(req,"action")=="check",log);}}finally{Monitor.Exit(Gate);}}
 }
}
